static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    long long *A = (long long *)malloc(sizeof(long long) * N);
    long long *B = (long long *)malloc(sizeof(long long) * N);
    long long *SA = (long long *)malloc(sizeof(long long) * N);
    long long *SB = (long long *)malloc(sizeof(long long) * N);

    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);
    for (int i = 0; i < N; i++) scanf("%lld", &B[i]);

    int already = 0;
    for (int i = 0; i < N; i++) {
        if (A[i] <= B[i]) already++;
        SA[i] = A[i];
        SB[i] = B[i];
    }

    qsort(SA, N, sizeof(long long), cmp_ll);
    qsort(SB, N, sizeof(long long), cmp_ll);

    for (int i = 0; i < N; i++) {
        if (SA[i] > SB[i]) {
            printf("No\n");
            free(A); free(B); free(SA); free(SB);
            return 0;
        }
    }

    for (int i = 0; i < N - 1; i++) {
        if (SA[i] <= SB[i + 1]) {
            printf("Yes\n");
            free(A); free(B); free(SA); free(SB);
            return 0;
        }
    }

    if (already < N) printf("No\n");
    else printf("Yes\n");

    free(A);
    free(B);
    free(SA);
    free(SB);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) { return *(int*)a - *(int*)b; }

int main() {
    int n;
    scanf("%d", &n);
    int A[n], B[n];
    for (int i = 0; i < n; i++) scanf("%d", &A[i]);
    for (int i = 0; i < n; i++) scanf("%d", &B[i]);

    int sortedA[n];
    for (int i = 0; i < n; i++) sortedA[i] = A[i];
    qsort(sortedA, n, sizeof(int), cmp);
    qsort(B, n, sizeof(int), cmp);

    for (int i = 0; i < n; i++) {
        if (sortedA[i] > B[i]) { printf("No\n"); return 0; }
    }
    printf("Yes\n");
    return 0;
}

