    vector<int> sortedA = A, sortedB = B;
    sort(sortedA.begin(), sortedA.end());
    sort(sortedB.begin(), sortedB.end());

    for (int i = 0; i < N; i++) {
        if (sortedA[i] > sortedB[i]) {
            cout << "No\n";
            return 0;
        }
    }

    // Check if we can fix with at most N-2 swaps
    int bad = 0;
    for (int i = 0; i < N; i++) {
        if (A[i] > B[i]) bad++;
    }

    if (bad > 2) {
        // If more than 2 are bad, we might still fix if we can rearrange via sorting
        // But since multiset condition passed, we can always do it if there exists 
        // some duplicate in B (so we can break cycles)
        bool dup = false;
        for (int i = 1; i < N; i++) {
            if (sortedB[i] == sortedB[i-1]) {
                dup = true;
                break;
            }
        }
        if (!dup) {
            cout << "No\n";
            return 0;
        }
    }

    cout << "Yes\n";
    return 0;
