int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> A(N), B(N);
    for (int i = 0; i < N; ++i) cin >> A[i];
    for (int i = 0; i < N; ++i) cin >> B[i];

    sort(A.begin(), A.end());
    sort(B.begin(), B.end());

    // Necessary condition: even after optimal rearrangement, A[i] must be <= B[i].
    for (int i = 0; i < N; ++i) {
        if (A[i] > B[i]) {
            cout << "No\n";
            return 0;
        }
    }

    // If there exists i such that A[i] <= B[i-1], then we can create a permutation
    // satisfying the condition with at most N-2 swaps.
    for (int i = 1; i < N; ++i) {
        if (A[i] <= B[i - 1]) {
            cout << "Yes\n";
            return 0;
        }
    }

    // Otherwise, all inequalities are "tight" in a strong sense.
    // Then the answer is Yes iff there is a duplicate in A (equivalently in the matching),
    // because duplicates allow reducing the required number of swaps.
    for (int i = 1; i < N; ++i) {
        if (A[i] == A[i - 1]) {
            cout << "Yes\n";
            return 0;
        }
    }

    cout << "No\n";
    return 0;
}

