import java.util.*;

public class Main {
    static int N;
    static int[] A, B;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        A = new int[N]; B = new int[N];
        for (int i = 0; i < N; i++) A[i] = sc.nextInt();
        for (int i = 0; i < N; i++) B[i] = sc.nextInt();

        int[] perm = new int[N];
        for (int i = 0; i < N; i++) perm[i] = i;
        boolean found = false;
        do {
            // check valid and count cycles
            boolean valid = true;
            for (int i = 0; i < N; i++) if (A[perm[i]] > B[i]) { valid = false; break; }
            if (valid) {
                int cycles = 0;
                boolean[] vis = new boolean[N];
                for (int i = 0; i < N; i++) if (!vis[i]) { cycles++; int j=i; while(!vis[j]){vis[j]=true;j=perm[j];} }
                int swapsNeeded = N - cycles;
                if (swapsNeeded <= N-2) { found = true; break; }
            }
        } while (nextPermutation(perm));
        System.out.println(found ? "Yes" : "No");
    }
    static boolean nextPermutation(int[] a) {
        int n=a.length,i=n-2;
        while(i>=0&&a[i]>=a[i+1])i--;
        if(i<0)return false;
        int j=n-1;while(a[j]<=a[i])j--;
        int t=a[i];a[i]=a[j];a[j]=t;
        for(int l=i+1,r=n-1;l<r;l++,r--){t=a[l];a[l]=a[r];a[r]=t;}
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int[] A = new int[N];
        int[] B = new int[N];

        for (int i = 0; i < N; i++) A[i] = fs.nextInt();
        for (int i = 0; i < N; i++) B[i] = fs.nextInt();

        int[] sortedA = A.clone();
        int[] sortedB = B.clone();
        Arrays.sort(sortedA);
        Arrays.sort(sortedB);

        // Necessary condition:
        // after any permutation of A, for all i, permA[i] <= B[i]
        // Equivalent to sortedA[i] <= sortedB[i] for all i.
        for (int i = 0; i < N; i++) {
            if (sortedA[i] > sortedB[i]) {
                System.out.println("No");
                return;
            }
        }

        // If there exists i such that sortedA[i] <= sortedB[i-1] (after sorting),
        // then we can create enough flexibility to realize the arrangement within <= N-2 swaps.
        for (int i = 1; i < N; i++) {
            if (sortedA[i] <= sortedB[i - 1]) {
                System.out.println("Yes");
                return;
            }
        }

        // Otherwise, matching is unique in sorted order.
        // Then it is possible iff original A already has a cycle decomposition
        // with at least 2 cycles relative to sorted order, so it can be done in <= N-2 swaps.
        Map<Integer, ArrayDeque<Integer>> pos = new HashMap<>();
        for (int i = 0; i < N; i++) {
            pos.computeIfAbsent(sortedA[i], k -> new ArrayDeque<>()).add(i);
        }

        int[] p = new int[N];
        for (int i = 0; i < N; i++) {
            p[i] = pos.get(A[i]).pollFirst();
        }

        boolean[] vis = new boolean[N];
        int cycles = 0;
        for (int i = 0; i < N; i++) {
            if (!vis[i]) {
                cycles++;
                int cur = i;
                while (!vis[cur]) {
                    vis[cur] = true;
                    cur = p[cur];
                }
            }
        }

        // Minimum swaps to sort permutation = N - cycles.
        // Need <= N - 2  <=> cycles >= 2.
        System.out.println(cycles >= 2 ? "Yes" : "No");
    }
}
